// Quick smoke test for the store module — exercises the @capacitor/preferences
// web implementation backed by localStorage in the jsdom environment vitest
// provides via this project's vitest.config.

import { describe, it, expect, beforeEach } from 'vitest';
import { Preferences } from '@capacitor/preferences';
import { createVersionedStore } from '../src/store';

async function rawStored(key: string): Promise<string | null> {
  // The web impl prefixes keys with "CapacitorStorage.", mirroring it here so
  // we can inspect the raw envelope to verify atomicity / durability.
  const { value } = await Preferences.get({ key });
  return value ?? null;
}

describe('createVersionedStore', () => {
  beforeEach(async () => {
    await Preferences.clear();
  });

  it('returns null when no value is stored', async () => {
    const store = createVersionedStore({ key: 'k', version: 1 });
    await expect(store.get()).resolves.toBeNull();
  });

  it('persists an envelope with version + data on set', async () => {
    const store = createVersionedStore({ key: 'k', version: 3 });
    await store.set({ hello: 'world' });

    const raw = await rawStored('k');
    expect(raw).not.toBeNull();
    const envelope = JSON.parse(raw as string);
    expect(envelope).toEqual({ version: 3, data: { hello: 'world' } });
  });

  it('returns stored data unchanged when versions match', async () => {
    const store = createVersionedStore({ key: 'k', version: 2 });
    await store.set({ a: 1 });
    await expect(store.get()).resolves.toEqual({ a: 1 });
  });

  it('runs the migration chain on read and persists the upgraded envelope', async () => {
    // Seed an old-version envelope directly so we can test the upgrade path.
    await Preferences.set({
      key: 'k',
      value: JSON.stringify({ version: 1, data: { name: 'Ada', years: 30 } }),
    });

    const store = createVersionedStore({
      key: 'k',
      version: 3,
      migrations: {
        // v1 -> v2: rename "years" to "age"
        1: (d: any) => ({ ...d, age: d.years, years: undefined }),
        // v2 -> v3: add a "status" field
        2: (d: any) => ({ ...d, status: 'active' }),
      },
    });

    const upgraded = await store.get();
    expect(upgraded).toEqual({ name: 'Ada', years: undefined, age: 30, status: 'active' });

    // Upgraded envelope should be durable: stored at the current version.
    const envelope = JSON.parse((await rawStored('k')) as string);
    expect(envelope.version).toBe(3);
    expect(envelope.data).toEqual(upgraded);

    // A second get() should hit the equal-version fast path and not re-run migrations.
    const again = await store.get();
    expect(again).toEqual(upgraded);
  });

  it('rejects (and leaves storage untouched) when a migration throws', async () => {
    const original = { version: 1, data: { foo: 'bar' } };
    await Preferences.set({ key: 'k', value: JSON.stringify(original) });

    const store = createVersionedStore({
      key: 'k',
      version: 2,
      migrations: {
        1: () => {
          throw new Error('boom');
        },
      },
    });

    await expect(store.get()).rejects.toThrow('boom');

    // Atomicity: storage should still hold the *original* envelope verbatim.
    expect(await rawStored('k')).toBe(JSON.stringify(original));
  });

  it('rejects when the stored version is newer than the current version', async () => {
    await Preferences.set({
      key: 'k',
      value: JSON.stringify({ version: 5, data: { x: 1 } }),
    });

    const store = createVersionedStore({ key: 'k', version: 4 });
    await expect(store.get()).rejects.toThrow();

    // Must not modify the stored value.
    const raw = await rawStored('k');
    expect(JSON.parse(raw as string).version).toBe(5);
  });

  it('remove() deletes the key so a subsequent get returns null', async () => {
    const store = createVersionedStore({ key: 'k', version: 1 });
    await store.set({ a: 1 });
    expect(await rawStored('k')).not.toBeNull();

    await store.remove();
    expect(await rawStored('k')).toBeNull();
    await expect(store.get()).resolves.toBeNull();
  });
});
